function subirCarpetaInstaladaComoPaquete(carpetaFile, tipo, autor) if carpetaFile==nil or not carpetaFile.exists() then return end local nombreLimpio=limpiarNombreParaNube(carpetaFile.getName()).."."..tipo local tempZip=File(getCarpetaDescargas(), nombreLimpio) if tempZip.exists() then tempZip.delete() end handler.post(Runnable{run=function() if status~=nil then status.setText("Comprimiendo: "..nombreLimpio) end end}) Thread(function() local comp=comprimirCarpetaAArchivo(carpetaFile, tempZip) handler.post(Runnable{run=function() if comp then subirArchivoASupabase(tempZip.getAbsolutePath(), nombreLimpio, autor) else if status~=nil then status.setText("Error comprimiendo") end end end}) end).start() end
function escanearCarpetasLector(lista) pcall(function() local function agregarDeRuta(ruta, tipo) local f=File(ruta) if not f.exists() then return end local hijos=f.listFiles() if hijos==nil then return end local len=Array.getLength(hijos) for i=0,len-1 do local c=hijos[i] if c.isDirectory() then table.insert(lista,{path=c.getAbsolutePath(), name=c.getName().." (INSTALADO."..tipo..")", tipo=tipo, esCarpeta=true, fileObj=c}) end end end agregarDeRuta(RUTA_PPK,"ppk") agregarDeRuta(RUTA_XPK,"xpk") agregarDeRuta(RUTA_SPK,"spk") end) end
