function subirAutorTexto(nom,autor) Thread(function() pcall(function() local na=nom..".autor.txt" local enc=URLEncoder.encode(na,"UTF-8") enc=string.gsub(enc,"%+","%%20") local url=URL(SUPABASE_URL.."/storage/v1/object/"..BUCKET_ENCODED.."/"..enc) local c=url.openConnection() c.setRequestMethod("POST") c.setDoOutput(true) c.setRequestProperty("apikey",SUPABASE_KEY) c.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) c.setRequestProperty("x-upsert","true") c.setRequestProperty("Content-Type","text/plain") local os=c.getOutputStream() os.write(String(autor).getBytes("UTF-8")) os.flush() os.close() c.getResponseCode() end) end).start() end
function subirArchivoASupabase(fp,nn,autor) if descargando then return end descargando=true local nn2=quitarNumerosAutomaticamente(nn) local nl=limpiarNombreParaNube(nn2) handler.post(Runnable{run=function() if status~=nil then status.setText("Subiendo: "..nl) end end}) Thread(function() local ok=false pcall(function() local file=File(fp) if not file.exists() then error("No existe") end local enc=URLEncoder.encode(nl,"UTF-8") enc=string.gsub(enc,"%+","%%20") local url=URL(SUPABASE_URL.."/storage/v1/object/"..BUCKET_ENCODED.."/"..enc) local c=url.openConnection() c.setRequestMethod("POST") c.setDoOutput(true) c.setConnectTimeout(30000) c.setReadTimeout(60000) c.setRequestProperty("apikey",SUPABASE_KEY) c.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) c.setRequestProperty("x-upsert","true") c.setRequestProperty("Content-Type","application/octet-stream") local fis=FileInputStream(file) local os=c.getOutputStream() local b=newByteArray(8192) local r=fis.read(b) while r~=-1 do os.write(b,0,r) r=fis.read(b) end os.flush() os.close() fis.close() if c.getResponseCode()>=200 and c.getResponseCode()<300 then ok=true end end) handler.post(Runnable{run=function() descargando=false if ok then subirAutorTexto(nl,autor) subirContadorNube(normalizarBase(nl),0) mostrarDialogoSubido(nl,autor) else if status~=nil then status.setText("Error al subir") end end end}) end).start() end
function subirMultiplesArchivos(lista,autor) if #lista==0 then return end if descargando then return end descargando=true local total=#lista local act=0 handler.post(Runnable{run=function() if status~=nil then status.setText("Subiendo 0/"..tostring(total)) end end}) Thread(function() for _,info in ipairs(lista) do pcall(function() local nl=limpiarNombreParaNube(quitarNumerosAutomaticamente(info.name)) local file=File(info.path) if not file.exists() then return end local enc=URLEncoder.encode(nl,"UTF-8") enc=string.gsub(enc,"%+","%%20") local url=URL(SUPABASE_URL.."/storage/v1/object/"..BUCKET_ENCODED.."/"..enc) local c=url.openConnection() c.setRequestMethod("POST") c.setDoOutput(true) c.setConnectTimeout(30000) c.setReadTimeout(60000) c.setRequestProperty("apikey",SUPABASE_KEY) c.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) c.setRequestProperty("x-upsert","true") c.setRequestProperty("Content-Type","application/octet-stream") local fis=FileInputStream(file) local os=c.getOutputStream() local b=newByteArray(8192) local r=fis.read(b) while r~=-1 do os.write(b,0,r) r=fis.read(b) end os.flush() os.close() fis.close() if c.getResponseCode()>=200 and c.getResponseCode()<300 then subirAutorTexto(nl,autor) subirContadorNube(normalizarBase(nl),0) end end) act=act+1 local ac=act handler.post(Runnable{run=function() if status~=nil then status.setText("Subiendo "..tostring(ac).."/"..tostring(total)) end end}) SystemClock.sleep(300) end handler.post(Runnable{run=function() descargando=false if explorerView then pcall(function() wm.removeView(explorerView) end) explorerView=nil end explorerSeleccionados={} explorerMultiSelect=false if status~=nil then status.setText("Subidos "..tostring(total).." archivos") end cargar(false) end}) end).start() end
function mostrarDialogoConfirmarSubida(fi) vibrarCorta() handler.post(Runnable{run=function() if dialogView then pcall(function() wm.removeView(dialogView) end) dialogView=nil end local f=LinearLayout(service) f.setOrientation(1) f.setBackgroundColor(Color.parseColor("#CC000000")) f.setPadding(40,40,40,40) f.setGravity(17) f.setFocusable(true) local c=LinearLayout(service) c.setOrientation(1) c.setBackgroundColor(Color.parseColor("#FF212121")) c.setPadding(30,30,30,30) local t=TextView(service) t.setText("Subir archivo?") t.setTextColor(Color.WHITE) c.addView(t) local tn=TextView(service) tn.setText("Original: "..fi.name.."\nLimpio: "..quitarNumerosAutomaticamente(fi.name)) tn.setTextColor(Color.parseColor("#FF1DB954")) c.addView(tn) local ia=EditText(service) ia.setText(miNombreAutor) ia.setTextColor(Color.WHITE) ia.setBackgroundColor(Color.parseColor("#FF333333")) c.addView(ia) local fb=LinearLayout(service) fb.setOrientation(0) local bc=Button(service) bc.setText("CANCELAR") bc.setBackgroundColor(Color.parseColor("#FF555555")) bc.setTextColor(Color.WHITE) bc.setLayoutParams(LinearLayout.LayoutParams(0,-2,1)) bc.setOnClickListener(View.OnClickListener{onClick=function(v) if dialogView then pcall(function() wm.removeView(dialogView) end) dialogView=nil end end}) local ba=Button(service) ba.setText("SUBIR LIMPIO") ba.setBackgroundColor(Color.parseColor("#FF1DB954")) ba.setTextColor(Color.WHITE) ba.setLayoutParams(LinearLayout.LayoutParams(0,-2,1)) ba.setOnClickListener(View.OnClickListener{onClick=function(v) local autor=tostring(ia.getText()):gsub("^%s+",""):gsub("%s+$","") if autor=="" then autor=miNombreAutor end if dialogView then pcall(function() wm.removeView(dialogView) end) dialogView=nil end if explorerView then pcall(function() wm.removeView(explorerView) end) explorerView=nil end subirArchivoASupabase(fi.path,fi.name,autor) end}) fb.addView(bc) fb.addView(ba) c.addView(fb) f.addView(c,LinearLayout.LayoutParams(-1,-2)) local p=WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT) p.gravity=17 pcall(function() p.type=WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY end) wm.addView(f,p) dialogView=f end}) end
function manejarVolver() vibrarCorta() if perfilActual~=nil and categoriaActual~=nil then local nombrePerfilGuardado=perfilActual categoriaActual=nil local obj=nil for _,pp in ipairs(todosPerfiles) do if pp.nombre_autor==nombrePerfilGuardado then obj=pp break end end if obj~=nil then perfilActual=nombrePerfilGuardado if listLayout~=nil then listLayout.removeAllViews() end if status~=nil then status.setText("Cargando categorias...") end mostrarBarraCargandoServidor("CARGANDO CATEGORIAS...") handler.postDelayed(Runnable{run=function() ocultarBarraCargandoServidor() mostrarDialogoCategorias(obj) end},300) else mostrarListaPerfiles() end return end if perfilActual~=nil then mostrarListaPerfiles() return end mostrarListaPerfiles() end
function filtrarYMostrarExplorador() if explorerListLayout==nil then return end handler.post(Runnable{run=function() if explorerListLayout==nil then return end explorerListLayout.removeAllViews() local temp={} for _,info in ipairs(explorerListaCompleta) do if explorerCategoriaActual=="lector" then table.insert(temp,info) else local low=info.name:lower() local co=false if explorerCategoriaActual=="ppk" and low:find("%.ppk") then co=true end if explorerCategoriaActual=="xpk" and low:find("%.xpk") then co=true end if explorerCategoriaActual=="spk" and low:find("%.spk") then co=true end if co then table.insert(temp,info) end end end local function crearFila(idx) if idx>#temp then if explorerTvStatus~=nil then explorerTvStatus.setText("Cat: "..explorerCategoriaActual:upper().." - "..tostring(#temp).." | Sel: "..tostring(#explorerSeleccionados)) end if explorerBtnSubirMulti~=nil then explorerBtnSubirMulti.setText("SUBIR ("..tostring(#explorerSeleccionados)..")") end return end local info=temp[idx] local row=LinearLayout(service) row.setOrientation(1) row.setPadding(20,12,20,12) local sel=false for _,s in ipairs(explorerSeleccionados) do if s.path==info.path then sel=true break end end if explorerMultiSelect and sel then row.setBackgroundColor(Color.parseColor("#331DB954")) else row.setBackgroundColor(Color.parseColor("#FF1E1E1E")) end row.setFocusable(true) local tn=TextView(service) local pref="[ ] " if sel then pref="[X] " end if explorerMultiSelect then tn.setText(pref..info.name) else tn.setText(info.name) end tn.setTextColor(Color.WHITE) local tp=TextView(service) tp.setText(info.path) tp.setTextColor(Color.parseColor("#FF888888")) tp.setTextSize(9) row.addView(tn) row.addView(tp) local ic=info row.setOnClickListener(View.OnClickListener{onClick=function(v) if ic.esCarpeta then vibrarLarga() subirCarpetaInstaladaComoPaquete(ic.fileObj, ic.tipo, miNombreAutor) else if explorerMultiSelect then local en=false for i,s in ipairs(explorerSeleccionados) do if s.path==ic.path then table.remove(explorerSeleccionados,i) en=true break end end if not en then table.insert(explorerSeleccionados,ic) end filtrarYMostrarExplorador() else mostrarDialogoConfirmarSubida(ic) end end end}) explorerListLayout.addView(row) handler.postDelayed(Runnable{run=function() crearFila(idx+1) end},15) end crearFila(1) end}) end
