function mostrarArchivosPorPerfilYCategoria(autor,tipo) vibrarCorta() if btnVolver~=nil then btnVolver.setVisibility(0) end if status~=nil then status.setText("Cargando "..autor.." - "..tipo:upper()) end if listLayout==nil then return end listLayout.removeAllViews() mostrarBarraCargandoServidor("CARGANDO ARCHIVOS...") handler.post(Runnable{run=function() local filtrados={} local al=autor:lower() for _,it in ipairs(todosArchivos) do local low=it.name:lower() if not low:find("%.autor%.txt") and not low:find("%.count%.txt$") then local fa=it.autor_cache if fa==nil or fa=="" then fa="aplicaciones company" end local co=false if fa:lower()==al then co=true end if al=="aplicaciones company" and fa:lower()=="aplicaciones" then co=true end if co then if tipo=="ppk" and low:find("%.ppk") then table.insert(filtrados,it) end if tipo=="xpk" and low:find("%.xpk") then table.insert(filtrados,it) end if tipo=="spk" and low:find("%.spk") then table.insert(filtrados,it) end end end end if status~=nil then status.setText(autor.." - "..tipo:upper().." ("..tostring(#filtrados)..")") end if #filtrados==0 then ocultarBarraCargandoServidor() local tv=TextView(service) tv.setText("No hay archivos "..tipo:upper()) tv.setTextColor(Color.WHITE) listLayout.addView(tv) return end local function crearFilaArchivo(i) if i<1 then ocultarBarraCargandoServidor() return end local item=filtrados[i] local row=LinearLayout(service) row.setOrientation(1) row.setPadding(20,15,20,15) row.setBackgroundColor(Color.parseColor("#FF1E1E1E")) row.setFocusable(true) row.setLayoutParams(LinearLayout.LayoutParams(-1,-2)) local tv=TextView(service) local cont=obtenerContador(item.name) tv.setText(item.name.."\nAutor: "..(item.autor_cache or "aplicaciones company").." | Descargas: "..tostring(cont)) tv.setTextColor(Color.WHITE) tv.setTextSize(13) row.addView(tv) fetchContadorNubeAsync(item.name,tv,item.autor_cache) local fb=LinearLayout(service) fb.setOrientation(0) local inst=estaInstalado(item.name) local bi=Button(service) bi.setTextSize(11) bi.setLayoutParams(LinearLayout.LayoutParams(0,-2,1)) local bd=Button(service) bd.setText("DESINSTALAR") bd.setBackgroundColor(Color.parseColor("#FFFF4444")) bd.setTextColor(Color.WHITE) bd.setLayoutParams(LinearLayout.LayoutParams(0,-2,1)) bd.setTextSize(11) if inst then bi.setText("INSTALADO") bi.setBackgroundColor(Color.parseColor("#FF555555")) bi.setEnabled(false) bd.setVisibility(0) else bi.setText("INSTALAR") bi.setBackgroundColor(Color.parseColor("#FF1DB954")) bi.setTextColor(Color.WHITE) bi.setEnabled(true) bd.setVisibility(8) end local id=item.id local nm=item.name bi.setOnClickListener(View.OnClickListener{onClick=function(v) descargar(id,nm,bi,bd) end}) bd.setOnClickListener(View.OnClickListener{onClick=function(v) desinstalarPlugin(nm) end}) fb.addView(bi) fb.addView(bd) if miNombreAutor:lower()=="aplicaciones company" or (item.autor_cache or ""):lower()==miNombreAutor:lower() then local be=Button(service) be.setText("ELIMINAR") be.setBackgroundColor(Color.parseColor("#FF880000")) be.setTextColor(Color.WHITE) be.setLayoutParams(LinearLayout.LayoutParams(0,-2,1)) be.setTextSize(11) local nm2=item.name be.setOnClickListener(View.OnClickListener{onClick=function(v) eliminarArchivoDeNube(nm2) end}) fb.addView(be) end row.addView(fb) listLayout.addView(row) handler.postDelayed(Runnable{run=function() crearFilaArchivo(i-1) end},20) end crearFilaArchivo(#filtrados) end}) end
function aplicarVisibilidadPorRol() local es=(miNombreAutor:lower()=="aplicaciones company") handler.post(Runnable{run=function() if es then if btnAddAdmin~=nil then btnAddAdmin.setVisibility(0) end if btnListaAdmins~=nil then btnListaAdmins.setVisibility(0) end if btnExplorer~=nil then btnExplorer.setVisibility(0) end if btnConfig~=nil then btnConfig.setVisibility(0) end if bu~=nil then bu.setVisibility(0) end if btnCerrarTienda~=nil then btnCerrarTienda.setVisibility(0) end else if btnAddAdmin~=nil then btnAddAdmin.setVisibility(8) end if btnListaAdmins~=nil then btnListaAdmins.setVisibility(8) end if btnExplorer~=nil then if rolActual=="invitado" then btnExplorer.setVisibility(8) else btnExplorer.setVisibility(0) end end if btnConfig~=nil then btnConfig.setVisibility(0) end if btnCerrarTienda~=nil then btnCerrarTienda.setVisibility(0) end end end}) end
function cargarPerfiles() Thread(function() local lista={} pcall(function() local url=URL(SUPABASE_URL.."/rest/v1/perfiles?select=username,rol,nombre_autor") local conn=url.openConnection() conn.setRequestProperty("apikey",SUPABASE_KEY) conn.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) if conn.getResponseCode()>=200 and conn.getResponseCode()<300 then local r=BufferedReader(InputStreamReader(conn.getInputStream())) local sb=StringBuilder() local l=r.readLine() while l~=nil do sb.append(l) l=r.readLine() end r.close() local arr=JSONArray(sb.toString()) for i=0,arr.length()-1 do local o=arr.getJSONObject(i) local nom=o.optString("nombre_autor","") if nom=="" then nom="aplicaciones company" end if nom:lower()~="angel" then table.insert(lista,{username=o.optString("username",""),rol=o.optString("rol",""),nombre_autor=nom}) end end end end) local tiene=false for _,pp in ipairs(lista) do if pp.nombre_autor:lower()=="aplicaciones company" then tiene=true break end end if not tiene then table.insert(lista,1,{username="aplicaciones company",rol="superadmin",nombre_autor="aplicaciones company"}) end lista=deduplicarPerfiles(lista) handler.post(Runnable{run=function() local nc=#lista if ultimoConteoPerfiles>0 and nc>ultimoConteoPerfiles then mostrarDialogoNuevoPerfil() end ultimoConteoPerfiles=nc todosPerfiles=lista verificarActualizacionTienda() if perfilActual==nil then mostrarListaPerfiles() end end}) end).start() end
function cargar(s) Thread(function() local files={} pcall(function() local offset=0 local limit=1000 while true do local urlList=URL(SUPABASE_URL.."/storage/v1/object/list/"..BUCKET_ENCODED) local conn=urlList.openConnection() conn.setRequestMethod("POST") conn.setDoOutput(true) conn.setConnectTimeout(20000) conn.setReadTimeout(20000) conn.setRequestProperty("Content-Type","application/json") conn.setRequestProperty("apikey",SUPABASE_KEY) conn.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) local body=String('{"prefix":"","limit":'..tostring(limit)..',"offset":'..tostring(offset)..',"sortBy":{"column":"created_at","order":"desc"}}') local os=conn.getOutputStream() os.write(body.getBytes("UTF-8")) os.flush() os.close() local code=conn.getResponseCode() local stream if code>=200 and code<300 then stream=conn.getInputStream() else stream=conn.getErrorStream() end local reader=BufferedReader(InputStreamReader(stream)) local sb=StringBuilder() local line=reader.readLine() while line~=nil do sb.append(line) line=reader.readLine() end reader.close() local arr=JSONArray(sb.toString()) if arr.length()==0 then break end for i=0,arr.length()-1 do local obj=arr.getJSONObject(i) local name=obj.getString("name") if name~=nil and name~="" and not name:find("/") and not name:lower():find("%.autor%.txt$") and not name:lower():find("%.count%.txt$") and name:lower()~=ACTUALIZACION_NOMBRE and name:lower()~=ACTUALIZACION_VERSION then table.insert(files,{name=name,id=obj.optString("id",name),autor_cache="aplicaciones company"}) end end if arr.length()<limit then break end offset=offset+limit SystemClock.sleep(200) end end) pcall(function() for _,f in ipairs(files) do local naf=f.name..".autor.txt" local enc=URLEncoder.encode(naf,"UTF-8") enc=string.gsub(enc,"%+","%%20") local urlA=SUPABASE_URL.."/storage/v1/object/public/"..BUCKET_ENCODED.."/"..enc local connA=URL(urlA).openConnection() connA.setConnectTimeout(3000) connA.setReadTimeout(3000) connA.setRequestProperty("apikey",SUPABASE_KEY) connA.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) if connA.getResponseCode()>=200 and connA.getResponseCode()<300 then local r=BufferedReader(InputStreamReader(connA.getInputStream())) local txt=r.readLine() r.close() if txt~=nil and txt:gsub("%s+","")~="" then f.autor_cache=txt:gsub("^%s+",""):gsub("%s+$","") end end end end) handler.post(Runnable{run=function() if not tiendaActiva then return end todosArchivos=files if perfilActual==nil then mostrarListaPerfiles() else if categoriaActual~=nil then mostrarArchivosPorPerfilYCategoria(perfilActual,categoriaActual) end end end}) end).start() end
function instalarPluginSilencioso(fn,fid,bi,bd) Thread(function() local ok=false pcall(function() local cc=getCarpetaDescargas() local ori=File(cc,fn) if not ori.exists() then ori=File("/sdcard/Download",fn) end if not ori.exists() then ori=File("/storage/emulated/0/Download",fn) end if not ori.exists() then error("no temp") end local low=fn:lower() local rb=RUTA_PPK if low:find("%.xpk") then rb=RUTA_XPK end if low:find("%.spk") then rb=RUTA_SPK end local cbd=File(rb) if not cbd.exists() then cbd.mkdirs() end local nc=fn:gsub("%.%w+$","") local df=File(cbd,nc) if df.exists() then borrarRecursivo(df) end df.mkdirs() local tf=nil local ex=false pcall(function() tf=extraerZipFix(ori,RUTA_TEMP) local h=tf.listFiles() local lh=getLength(h) if lh>0 then ex=true if lh==1 and h[0].isDirectory() then local u=h[0] local hu=u.listFiles() local lhu=getLength(hu) if lhu>0 then for i=0,lhu-1 do copiarCarpetaCompleta(hu[i],File(df,hu[i].getName())) end else copiarCarpetaCompleta(u,df) end else for i=0,lh-1 do copiarCarpetaCompleta(h[i],File(df,h[i].getName())) end end end end) if not ex then if tf~=nil then borrarRecursivo(tf) end local da=File(df,fn) local i=FileInputStream(ori) local o=FileOutputStream(da) local b=newByteArray(8192) local r=i.read(b) while r~=-1 do o.write(b,0,r) r=i.read(b) end i.close() o.close() else if tf~=nil then borrarRecursivo(tf) end end pcall(function() ori.delete() end) if fid~=nil then guardarVersionInstalada(normalizarBase(fn),fid) end ok=true end) handler.post(Runnable{run=function() if ok then incrementarContador(fn) if status~=nil then status.setText("Instalado: "..fn.." Descargas: "..tostring(obtenerContador(fn))) end if bi~=nil then bi.setText("INSTALADO") bi.setBackgroundColor(Color.parseColor("#FF555555")) bi.setEnabled(false) end if bd~=nil then bd.setVisibility(0) end mostrarDialogoInstalado(fn) if perfilActual~=nil and categoriaActual~=nil then handler.postDelayed(Runnable{run=function() mostrarArchivosPorPerfilYCategoria(perfilActual,categoriaActual) end},600) end else if status~=nil then status.setText("Error instalando "..fn) end if bi~=nil then bi.setText("INSTALAR") bi.setBackgroundColor(Color.parseColor("#FF1DB954")) bi.setEnabled(true) end mostrarDialogoErrorInstalar(fn,"No se pudo instalar") end end}) end).start() end
function descargar(fid,fname,bi,bd) if descargando then return end vibrarCorta() local myFid=tostring(fid) local myFn=limpiarNombre(tostring(fname)) local car=getCarpetaDescargas() descargando=true bi.setText("DESCARGANDO...") bi.setBackgroundColor(Color.parseColor("#FFFFA500")) bi.setEnabled(false) Thread(function() local suc=false local ff=myFn pcall(function() local enc=URLEncoder.encode(myFn,"UTF-8") local en=string.gsub(enc,"%+","%%20") local fu=SUPABASE_URL.."/storage/v1/object/public/"..BUCKET_ENCODED.."/"..en local u=URL(fu) local c=u.openConnection() c.setConnectTimeout(30000) c.setReadTimeout(60000) c.setRequestProperty("apikey",SUPABASE_KEY) c.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) local inp=BufferedInputStream(c.getInputStream()) if not car.exists() then car.mkdirs() end local of=File(car,ff) if of.exists() then of.delete() end local ou=FileOutputStream(of) local b=newByteArray(8192) local r=inp.read(b) while r~=-1 do ou.write(b,0,r) r=inp.read(b) end ou.close() inp.close() suc=true end) handler.post(Runnable{run=function() descargando=false if suc then bi.setText("INSTALANDO...") instalarPluginSilencioso(ff,myFid,bi,bd) else bi.setText("INSTALAR") bi.setBackgroundColor(Color.parseColor("#FF1DB954")) bi.setEnabled(true) mostrarDialogoErrorInstalar(ff,"No se pudo descargar") end end}) end).start() end
