function subirTextoActualizacion(nombre,txt) local ok,err=pcall(function() local enc=URLEncoder.encode(nombre,"UTF-8") enc=string.gsub(enc,"+","%%20") local c=URL(SUPABASE_URL.."/storage/v1/object/"..BUCKET_ENCODED.."/"..enc).openConnection() c.setRequestMethod("POST") c.setDoOutput(true) c.setConnectTimeout(30000) c.setReadTimeout(60000) c.setRequestProperty("apikey",SUPABASE_KEY) c.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) c.setRequestProperty("x-upsert","true") c.setRequestProperty("Content-Type","text/plain") local os=c.getOutputStream() os.write(String(txt).getBytes("UTF-8")) os.close() local code=c.getResponseCode() if code<200 or code>=300 then error("Servidor respondió HTTP "..tostring(code)) end end) return ok,err end
function subirPaqueteActualizacion(archivo,nombre,version,cerrar) if descargando then return end descargando=true Thread(function() local ok,err=pcall(function() local file=File(archivo) if not file.exists() then error("No existe el paquete generado") end local enc=URLEncoder.encode(nombre,"UTF-8") enc=string.gsub(enc,"+","%%20") local c=URL(SUPABASE_URL.."/storage/v1/object/"..BUCKET_ENCODED.."/"..enc).openConnection() c.setRequestMethod("POST") c.setDoOutput(true) c.setConnectTimeout(30000) c.setReadTimeout(120000) c.setRequestProperty("apikey",SUPABASE_KEY) c.setRequestProperty("Authorization","Bearer "..SUPABASE_KEY) c.setRequestProperty("x-upsert","true") c.setRequestProperty("Content-Type","application/octet-stream") local fis=FileInputStream(file) local os=c.getOutputStream() local b=newByteArray(8192) local r=fis.read(b) while r~=-1 do os.write(b,0,r) r=fis.read(b) end fis.close() os.close() local code=c.getResponseCode() if code<200 or code>=300 then error("Error subiendo paquete: HTTP "..tostring(code)) end local vok,verr=subirTextoActualizacion(ACTUALIZACION_VERSION,version) if not vok then error(verr or "No se pudo guardar la versión") end end) handler.post(Runnable{run=function() descargando=false if ok then if status~=nil then status.setText("Actualización subida: "..version) end mostrarDialogoActualizacionResultado(true,version,nil) else if status~=nil then status.setText("Error al subir actualización") end mostrarDialogoActualizacionResultado(false,nil,err) end end}) end).start() end
