nombre_autor\":\"([^\"]+)\"") if rt~=nil then enc=true r=rt au=at end end end) handler.post(Runnable{run=function() if enc then usuarioActual=user rolActual=r miNombreAutor=au if miNombreAutor==nil or miNombreAutor=="" then miNombreAutor="aplicaciones company" end if dialogView then pcall(function() wm.removeView(dialogView) end) dialogView=nil end if status~=nil then status.setText("Hola "..miNombreAutor) end aplicarVisibilidadPorRol() cargarPerfiles() cargar(false) handler.postDelayed(Runnable{run=function() mostrarBienvenida() end},500) else if dialogView then pcall(function() wm.removeView(dialogView) end) dialogView=nil end borrarLoginGuardado() mostrarDialogoDescartado() end end}) end).start() end
